CREATE DATABASE IF NOT EXISTS acedamic_staff CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE acedamic_staff;
CREATE TABLE IF NOT EXISTS users(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(80) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,full_name VARCHAR(160) NOT NULL,role ENUM('admin','student','department_head','peer','self','academic_admin','committee','college_admin','dean','academic_affairs','archive','concerned_office') NOT NULL DEFAULT 'student',department VARCHAR(160) DEFAULT NULL,instructor_id INT UNSIGNED DEFAULT NULL,is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,KEY idx_users_instructor_id (instructor_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS instructors(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(160) NOT NULL,college VARCHAR(160) DEFAULT NULL,department VARCHAR(160) NOT NULL,employee_code VARCHAR(60) DEFAULT NULL,is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS departments(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL UNIQUE,is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS courses(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,department_id INT UNSIGNED NOT NULL,course_code VARCHAR(60) NOT NULL,course_title VARCHAR(160) NOT NULL,description TEXT DEFAULT NULL,is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_course_department_code(department_id,course_code),KEY idx_courses_department_active(department_id,is_active),CONSTRAINT fk_courses_department FOREIGN KEY(department_id) REFERENCES departments(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS evaluation_questions(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,evaluator_type ENUM('student','department_head','peer','self') NOT NULL,section VARCHAR(160) NOT NULL,question_text TEXT NOT NULL,sort_order INT NOT NULL DEFAULT 0,is_active TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS evaluations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,instructor_id INT UNSIGNED NOT NULL,course_id INT UNSIGNED DEFAULT NULL,evaluator_user_id INT UNSIGNED NOT NULL,evaluator_type ENUM('student','department_head','peer','self') NOT NULL,academic_year VARCHAR(40) NOT NULL,semester VARCHAR(10) DEFAULT NULL,course_title VARCHAR(160) DEFAULT NULL,course_code VARCHAR(60) DEFAULT NULL,batch_no VARCHAR(10) DEFAULT NULL,strengths TEXT DEFAULT NULL,improvements TEXT DEFAULT NULL,status ENUM('submitted','committee_review','college_review','academic_affairs','archived','returned') NOT NULL DEFAULT 'submitted',workflow_note TEXT DEFAULT NULL,reviewed_by INT UNSIGNED DEFAULT NULL,reviewed_at DATETIME DEFAULT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,KEY idx_evaluations_course_id(course_id),FOREIGN KEY(instructor_id) REFERENCES instructors(id),FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE SET NULL,FOREIGN KEY(evaluator_user_id) REFERENCES users(id),FOREIGN KEY(reviewed_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS messages(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,sender_user_id INT UNSIGNED NOT NULL,recipient_user_id INT UNSIGNED NOT NULL,instructor_id INT UNSIGNED DEFAULT NULL,evaluation_id BIGINT UNSIGNED DEFAULT NULL,subject VARCHAR(180) NOT NULL,body TEXT NOT NULL,message_type VARCHAR(80) NOT NULL DEFAULT 'Official Message',read_at DATETIME DEFAULT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_messages_recipient_read(recipient_user_id,read_at,created_at),KEY idx_messages_instructor(instructor_id),FOREIGN KEY(sender_user_id) REFERENCES users(id),FOREIGN KEY(recipient_user_id) REFERENCES users(id),FOREIGN KEY(instructor_id) REFERENCES instructors(id) ON DELETE SET NULL,FOREIGN KEY(evaluation_id) REFERENCES evaluations(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS evaluation_responses(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,evaluation_id BIGINT UNSIGNED NOT NULL,question_id INT UNSIGNED NOT NULL,rating TINYINT DEFAULT NULL,is_na TINYINT(1) NOT NULL DEFAULT 0,FOREIGN KEY(evaluation_id) REFERENCES evaluations(id) ON DELETE CASCADE,FOREIGN KEY(question_id) REFERENCES evaluation_questions(id),UNIQUE KEY uq_eval_question(evaluation_id,question_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS workflow_log(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,evaluation_id BIGINT UNSIGNED NOT NULL,actor_user_id INT UNSIGNED NOT NULL,action VARCHAR(80) NOT NULL,note TEXT DEFAULT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(evaluation_id) REFERENCES evaluations(id) ON DELETE CASCADE,FOREIGN KEY(actor_user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS institutional_records(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,evaluation_id BIGINT UNSIGNED NOT NULL,archive_level ENUM('department','college','university') NOT NULL DEFAULT 'department',archive_reference VARCHAR(120) DEFAULT NULL,archived_by INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(evaluation_id) REFERENCES evaluations(id),FOREIGN KEY(archived_by) REFERENCES users(id)) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS admin_audit_log(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,actor_user_id INT UNSIGNED NOT NULL,action VARCHAR(80) NOT NULL,details TEXT DEFAULT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_admin_audit_actor(actor_user_id),KEY idx_admin_audit_created(created_at),FOREIGN KEY(actor_user_id) REFERENCES users(id)) ENGINE=InnoDB;
